def tbl(cap,hd,rows):
    return '<div class="table-wrap"><table class="data"><caption>%s</caption><thead><tr>%s</tr></thead><tbody>%s</tbody></table></div>'%(cap,"".join('<th scope="col">%s</th>'%h for h in hd),"".join("<tr>"+'<th scope="row">%s</th>'%r[0]+"".join("<td>%s</td>"%c for c in r[1:])+"</tr>" for r in rows))
def faq(items): return "".join("<p><strong>%s</strong> %s</p>"%i for i in items)

